"""Interface servida localmente; sem CDN, fontes remotas ou telemetria."""
PAGINA = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Separação de pedidos</title>
<style nonce="__NONCE__">
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#192f39;background:#f2f5f4;font-size:16px;font-synthesis:none;--green:#176950;--muted:#53676f}
*{box-sizing:border-box}body{margin:0;line-height:1.45}header{background:#173b36;color:white;padding:28px max(24px,calc((100vw - 1200px)/2))}header p{color:#cee1da;margin:5px 0 0;max-width:65ch}h1{font-size:28px;letter-spacing:-.6px;margin:0}h2{font-size:19px;margin:0 0 8px}main{max-width:1250px;margin:auto;padding:24px}.local{float:right;font-size:13px;border:1px solid #78968b;border-radius:20px;padding:5px 11px;margin-top:5px}.card{background:#fff;border:1px solid #d7e1dd;border-radius:12px;padding:22px;margin-bottom:18px}.topgrid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px}.topgrid .card{margin:0}p{margin:0 0 12px}.hint{font-size:13px;color:var(--muted);max-width:75ch}.drop{background:#f6faf8;border:1px dashed #8cae9c;padding:18px;border-radius:8px;display:block;cursor:pointer}.drop strong{display:block;margin-bottom:4px}input[type=file]{max-width:100%;margin-top:10px;font-size:14px}button,input,select{font:inherit}button{border:1px solid #b8c9c1;border-radius:7px;padding:9px 14px;background:#fff;color:#24443a;font-size:14px;font-weight:600;cursor:pointer;white-space:nowrap}button:hover{background:#f1f7f3}button:disabled{opacity:.45;cursor:default}.primary{background:var(--green);border-color:var(--green);color:white}.primary:hover{background:#11513d}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.spacer{flex:1}input[type=text],select{border:1px solid #b6c9bf;border-radius:7px;padding:9px 11px;background:white;color:#192f39;min-width:0}input[type=text]{width:100%}.scan{flex:1}.metrics{display:flex;gap:24px;align-items:center;flex-wrap:wrap;margin:23px 0 16px}.metric strong{font-size:27px;display:block;line-height:1.2}.metric span{font-size:13px;color:var(--muted)}.filters{display:grid;grid-template-columns:1fr 210px 210px;gap:12px;margin-bottom:12px}.field{display:block;font-size:13px;font-weight:600;margin-bottom:5px}#message{margin:16px 0 0;padding:12px 15px;border-radius:8px;background:#e5f0e9;color:#1d4d36;white-space:pre-wrap}#message.error{background:#fcedea;color:#8a2c18}#message:empty{display:none}#warnings{background:#fff4d8;color:#654713;border-radius:8px;margin:15px 0;padding:12px 16px;font-size:13px}#warnings[hidden]{display:none}#warnings ul{margin:5px 0;max-height:170px;overflow:auto;padding-left:20px}.tablewrap{overflow:auto;border:1px solid #d9e2dd;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;background:#f1f5f3;padding:11px 12px;font-size:12px;color:#455e52;font-weight:650;white-space:nowrap}td{padding:13px 12px;border-top:1px solid #e3eae6;vertical-align:top}.product{min-width:230px;max-width:470px}.meta{font-size:12px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere}.badge{display:inline-block;font-size:11px;font-weight:700;padding:3px 7px;border-radius:4px;white-space:nowrap;margin-bottom:5px}.ml{background:#fff1b5;color:#5f4b00}.tt{background:#e9e7f3;color:#443c63}.dhoje{background:#176950;color:#fff}.datras{background:#fbe3dc;color:#8a2c18}.dfut{background:#e9eeec;color:#455e52}.dsem{background:#fff1d0;color:#6a4a00}.code{font-variant-numeric:tabular-nums;font-weight:650;font-size:13px;white-space:nowrap}.qty{text-align:right;font-weight:700;font-size:18px}.select{width:40px}input[type=checkbox]{width:18px;height:18px;accent-color:var(--green);cursor:pointer;margin:0}.bottom{margin-top:18px;position:sticky;bottom:10px;background:#fff;border:1px solid #d7e1dd;box-shadow:0 3px 16px #183b3410;border-radius:10px;padding:15px 18px}.bottom .hint{margin:4px 0 0}#partial{color:#a34313;font-size:13px;margin-bottom:8px}.empty{text-align:center;padding:40px 20px;color:var(--muted)}.empty strong{display:block;color:#253e33;font-size:17px;margin-bottom:5px}footer{text-align:center;color:var(--muted);font-size:12px;margin:18px 0 12px}a{color:#176950}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #55a786;outline-offset:2px}.smallbtn{font-size:12px;padding:4px 7px;margin-top:5px;font-weight:500}.busy{font-size:13px;color:#4f675a;margin-top:10px}progress{width:100%;height:5px;accent-color:var(--green)}
@media(max-width:750px){.dtxt{display:none}.topgrid{grid-template-columns:1fr}main{padding:15px}header{padding:22px 18px}.local{float:none;display:inline-block;margin:0 0 10px}h1{font-size:25px}.filters{grid-template-columns:1fr}.bottom{position:static}.card{padding:17px}.metrics{gap:18px}}
</style></head><body>
<header><span class="local">Local no seu Mac</span><h1>Separação de pedidos</h1><p>Importe as vendas. Só os pacotes com despacho hoje entram marcados no checklist A4.</p></header>
<main>
<div class="topgrid"><section class="card"><h2>1. Adicione as planilhas</h2><p class="hint">Relatórios de vendas do Mercado Livre e de pedidos do TikTok Shop. Você pode enviar um ou vários arquivos XLSX.</p>
<label class="drop" id="drop"><strong>Escolher arquivos ou arrastar aqui</strong><span class="hint">Até 12 MB por arquivo. As plataformas são identificadas automaticamente.</span><input id="files" type="file" accept=".xlsx" multiple aria-label="Escolher planilhas XLSX"></label>
<div class="busy" id="busy" hidden><span>Lendo as planilhas localmente com Docling… Aguarde.</span><progress aria-label="Processando planilhas"></progress></div>
<p class="hint" id="filelist" style="margin:10px 0 0">Nenhuma planilha importada.</p></section>
<section class="card"><h2>2. Localize pela etiqueta <span class="hint">(opcional)</span></h2><p class="hint">Digite ou bipe o envio, rastreio ou número do pedido. O pacote completo será adicionado à seleção. Para escolher apenas ele, use antes “Desmarcar todos”.</p>
<form id="scanform" class="row"><label class="scan"><span class="field">Código completo da etiqueta</span><input id="scan" type="text" placeholder="Envio, rastreio ou pedido" autocomplete="off"></label><button id="scanbutton" type="submit">Selecionar pacote</button></form>
<p class="hint" style="margin-top:12px">O código precisa existir na planilha. Esta versão não faz upload nem leitura de fotos/PDFs de etiquetas.</p></section></div>
<div id="message" role="status" aria-live="polite"></div><div id="warnings" hidden><strong>Confira antes de separar</strong><ul id="warninglist"></ul></div>
<div class="metrics"><div class="metric"><strong id="packcount">0</strong><span>pacotes selecionados</span></div><div class="metric"><strong id="itemcount">0</strong><span>itens selecionados</span></div><div class="metric"><strong id="unitcount">0</strong><span>unidades de venda</span></div><div class="spacer"></div><button id="reset" type="button">Iniciar novo lote</button></div>
<section class="card"><h2>3. Escolha os produtos</h2><div class="filters"><label><span class="field">Buscar produto, SKU, destinatário ou código</span><input id="search" type="text" placeholder="Buscar nos pedidos importados"></label><label><span class="field">Plataforma</span><select id="channel"><option value="">Todas as plataformas</option><option>Mercado Livre</option><option>TikTok Shop</option></select></label><label><span class="field">Despacho</span><select id="ship"><option value="hoje">Hoje e atrasados</option><option value="outros">Outros dias</option><option value="">Todos os prazos</option></select></label></div>
<div class="row" style="margin-bottom:12px"><button id="selectvisible" type="button">Selecionar só os resultados</button><button id="unselect" type="button">Desmarcar todos</button><span class="hint" id="visiblecount">0 itens</span></div>
<p class="hint">Ao importar, só os pacotes com despacho hoje (ou atrasados) ficam marcados. Os de outros dias ficam desmarcados; veja em Despacho → Outros dias. O PDF inclui todos os itens marcados, mesmo fora do filtro.</p>
<div class="tablewrap"><table><thead><tr><th class="select">Incluir</th><th>Despacho</th><th>Plataforma / etiqueta</th><th>Destinatário / pedido</th><th>Produto / variação</th><th>Qtd.</th></tr></thead><tbody id="rows"></tbody></table><div class="empty" id="empty"><strong>Seu próximo lote começa aqui</strong>Adicione as planilhas para visualizar os produtos.</div></div>
</section>
<div class="bottom"><div id="partial" role="status"></div><div class="row"><div><strong>Checklist de separação e conferência</strong><p class="hint">PDF A4 com duas conferências por item: Separado e embalado, e Despachado. Lotes maiores continuam em outras páginas.</p></div><div class="spacer"></div><button class="primary" id="download" disabled>Baixar PDF A4</button></div></div>
<footer>Dados mantidos apenas nesta sessão local. Kits não são desmembrados. Confira sempre a etiqueta física.</footer>
</main>
<script nonce="__NONCE__">
const token='__TOKEN__';let items=[],selected=new Set(),files=[],processing=false;
const $=id=>document.getElementById(id);
const HOJE=(()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');})();
const SEM=['dom','seg','ter','qua','qui','sex','sáb'];
function prazo(i){if(!i.ship_date)return 'sem';if(i.ship_late||i.ship_date<HOJE)return 'atrasado';return i.ship_date===HOJE?'hoje':'futuro';}
function doDia(){const g=new Set();for(const i of items)if(['hoje','atrasado'].includes(prazo(i)))g.add(i.group);return g;}
function selo(i){const p=prazo(i);if(p==='hoje')return '<span class="badge dhoje">Hoje</span>';if(p==='atrasado')return '<span class="badge datras">Atrasado</span>';if(p==='sem')return '<span class="badge dsem">Confira o prazo</span>';const [a,m,d]=i.ship_date.split('-');return `<span class="badge dfut">${SEM[new Date(+a,m-1,+d).getDay()]} ${d}/${m}</span>`;}
function resumoDia(){const g=doDia(),todos=new Set(items.map(i=>i.group));return `${g.size} pacote(s) para despachar hoje (marcados), ${todos.size-g.size} de outros dias ou sem prazo (desmarcados).`;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
async function api(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Session-Token':token},body:JSON.stringify(data)});if(!r.ok){const j=await r.json();throw Error(j.error||'Não foi possível concluir.');}return r;}
function visible(){const q=norm($('search').value),f=$('ship').value,g=doDia();return items.filter(i=>(!$('channel').value||i.channel===$('channel').value)&&(!f||(f==='hoje')===g.has(i.group))&&norm([i.title,i.sku,i.variation,i.buyer,i.code,i.order,i.package,i.tracking].join(' ')).includes(q));}
function partialGroups(){const all=new Map(),chosen=new Map();for(const i of items){all.set(i.group,(all.get(i.group)||0)+1);if(selected.has(i.id))chosen.set(i.group,(chosen.get(i.group)||0)+1);}return [...chosen].filter(([g,n])=>n<all.get(g)).map(([g])=>g);}
function counters(){const list=items.filter(i=>selected.has(i.id));$('itemcount').textContent=list.length;$('unitcount').textContent=list.reduce((a,i)=>a+i.quantity,0);$('packcount').textContent=new Set(list.map(i=>i.group)).size;$('download').disabled=processing||!list.length;const n=partialGroups().length;$('partial').textContent=n?`Atenção: ${n} pacote(s) com seleção parcial. Selecione todos os produtos do pacote para evitar envio incompleto.`:'';}
function render(){const list=visible();$('rows').innerHTML=list.map(i=>`<tr><td><input type="checkbox" data-item="${esc(i.id)}" aria-label="Incluir ${esc(i.title)}" ${selected.has(i.id)?'checked':''}></td><td>${selo(i)}<div class="meta dtxt" title="${esc(i.ship_text)}">${esc((i.ship_text||'').slice(0,60))}</div></td><td><span class="badge ${i.channel==='Mercado Livre'?'ml':'tt'}">${esc(i.channel)}</span><div class="code">${esc(i.code||'Sem envio/rastreio')}</div><button class="smallbtn" data-group="${esc(i.group)}" type="button">Selecionar pacote</button></td><td>${esc(i.buyer||'Não informado')}<div class="meta">Pedido ${esc(i.order)}</div><div class="meta">${esc(i.status)}</div></td><td class="product">${esc(i.title)}<div class="meta">${esc(i.variation)}</div><div class="meta">${esc(i.sku?'SKU: '+i.sku:'ID: '+(i.product_id||'não informado'))}</div></td><td class="qty">${i.quantity}</td></tr>`).join('');$('empty').hidden=!!list.length;if(items.length&&!list.length)$('empty').innerHTML='<strong>Nenhum resultado</strong>Altere a busca ou os filtros de plataforma e despacho.';else if(!items.length)$('empty').innerHTML='<strong>Seu próximo lote começa aqui</strong>Adicione as planilhas para visualizar os produtos.';$('visiblecount').textContent=`${list.length} de ${items.length} itens`;$('filelist').textContent=files.length?'Importados: '+files.join(' · '):'Nenhuma planilha importada.';counters();}
function setBusy(b){processing=b;$('busy').hidden=!b;for(const id of ['files','reset','scanbutton','selectvisible','unselect'])$(id).disabled=b;counters();}
function toBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Falha ao abrir o arquivo.'));reader.readAsDataURL(file);});}
async function upload(filelist){if(processing)return;const list=[...filelist];if(!list.length)return;try{if(list.length>10)throw Error('Envie até 10 planilhas por vez.');if(list.some(f=>!f.name.toLowerCase().endsWith('.xlsx')))throw Error('Use apenas planilhas XLSX.');if(list.some(f=>f.size>12*1024*1024)||list.reduce((s,f)=>s+f.size,0)>30*1024*1024)throw Error('Limite: 12 MB por arquivo e 30 MB por envio.');setBusy(true);message('Importando… Isso pode levar alguns segundos por arquivo.');const payload=[];for(const f of list)payload.push({name:f.name,data:await toBase64(f)});const old=new Set(items.map(i=>i.id));const j=await(await api('/api/import',{files:payload})).json();items=j.items;files=j.files;const dia=doDia();for(const i of items)if(!old.has(i.id)&&dia.has(i.group))selected.add(i.id);$('warninglist').innerHTML=j.warnings.map(w=>`<li>${esc(w)}</li>`).join('');$('warnings').hidden=!j.warnings.length;message(`${j.added} item(ns) adicionado(s). ${j.duplicates} repetido(s) ignorado(s). ${resumoDia()} Confira e baixe o PDF.`);render();}catch(e){message(e.message,true);}finally{setBusy(false);$('files').value='';}}
$('files').addEventListener('change',e=>upload(e.target.files));$('drop').addEventListener('dragover',e=>e.preventDefault());$('drop').addEventListener('drop',e=>{e.preventDefault();upload(e.dataTransfer.files);});
$('search').addEventListener('input',render);$('channel').addEventListener('change',render);$('ship').addEventListener('change',render);
$('rows').addEventListener('change',e=>{const id=e.target.dataset.item;if(id){e.target.checked?selected.add(id):selected.delete(id);counters();}});
$('rows').addEventListener('click',e=>{const group=e.target.dataset.group;if(group){for(const i of items)if(i.group===group)selected.add(i.id);render();}});
$('selectvisible').onclick=()=>{selected=new Set(visible().map(i=>i.id));render();};$('unselect').onclick=()=>{selected.clear();render();};
$('scanform').onsubmit=async e=>{e.preventDefault();try{const j=await(await api('/api/match',{code:$('scan').value})).json();for(const id of j.ids)selected.add(id);message(`Pacote localizado: ${j.ids.length} item(ns) selecionado(s).`);render();}catch(e){message(e.message,true);}};
$('reset').onclick=async()=>{if(!confirm('Iniciar um novo lote? A seleção e os dados importados serão removidos apenas desta sessão. Os arquivos originais não serão alterados.'))return;try{await api('/api/reset',{});items=[];files=[];selected.clear();$('warnings').hidden=true;$('search').value='';$('channel').value='';$('ship').value='hoje';$('scan').value='';message('Novo lote iniciado. Adicione as planilhas.');render();}catch(e){message(e.message,true);}};
$('download').onclick=async()=>{const partial=partialGroups().length;if(partial&&!confirm(`Você selecionou apenas parte de ${partial} pacote(s). O PDF será marcado como seleção parcial. Gerar mesmo assim?`))return;try{$('download').disabled=true;const r=await api('/api/pdf',{ids:[...selected],allow_partial:!!partial});const blob=await r.blob();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=r.headers.get('X-Filename')||'Checklist-separacao.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('PDF gerado. Abra o arquivo baixado e imprima em A4, escala 100%.');}catch(e){message(e.message,true);}finally{counters();}};
(async()=>{try{const r=await fetch('/api/state');if(!r.ok)throw Error('Não foi possível carregar a sessão.');const j=await r.json();items=j.items;files=j.files;const dia=doDia();selected=new Set(items.filter(i=>dia.has(i.group)).map(i=>i.id));$('warninglist').innerHTML=j.warnings.map(w=>`<li>${esc(w)}</li>`).join('');$('warnings').hidden=!j.warnings.length;render();}catch(e){message(e.message,true);}})();
</script></body></html>'''
